  &reftitle.examples;



    Basic bindto usage example


<?php
// connect to the internet using the '192.168.0.100' IP
$opts = array(
    'socket' => array(
        'bindto' => '192.168.0.100:0',
    ),
);


// connect to the internet using the '192.168.0.100' IP and port '7000'
$opts = array(
    'socket' => array(
        'bindto' => '192.168.0.100:7000',
    ),
);


// connect to the internet using the '2001:db8::1' IPv6 address
// and port '7000'
$opts = array(
    'socket' => array(
        'bindto' => '[2001:db8::1]:7000',
    ),
);


// connect to the internet using port '7000'
$opts = array(
    'socket' => array(
        'bindto' => '0:7000',
    ),
);


// create the context...
$context = stream_context_create($opts);

// ...and use it to fetch the data
echo file_get_contents('http://www.example.com', false, $context);

?>




    Enabling TCP keepalive, as of PHP 8.6.0


<?php
// Send the first keepalive probe after 60 seconds of inactivity,
// then one every 10 seconds, and drop the connection
// after 3 unanswered probes
$opts = [
    'socket' => [
        'so_keepalive' => true,
        'tcp_keepidle' => 60,
        'tcp_keepintvl' => 10,
        'tcp_keepcnt' => 3,
    ],
];

$context = stream_context_create($opts);

$fp = stream_socket_client('tcp://www.example.com:80', context: $context);
?>
